helper='''// Self-contained because Page.evaluate serializes this function into the browser.
async function waitForInitialHistory({ id, text }: { id: string; text: string }) {
  await new Promise<void>((resolve, reject) => {
    let frame = 0;
    const visible = (element: Element | null): element is HTMLElement => {
      if (!(element instanceof HTMLElement)) return false;
      const rect = element.getBoundingClientRect();
      const style = getComputedStyle(element);
      return rect.width > 0 && rect.height > 0 &&
        style.visibility === "visible" && style.display !== "none";
    };
    const cleanup = () => {
      observer.disconnect();
      clearTimeout(timer);
      cancelAnimationFrame(frame);
    };
    const schedule = () => {
      if (!frame) frame = requestAnimationFrame(() => { frame = 0; check(); });
    };
    const check = () => {
      try {
        const log = document.querySelector('[role="log"]');
        const row = log?.querySelector(`[data-message-id="${id}"]`) ?? null;
        if (visible(log) && visible(row) &&
          [...row.querySelectorAll("*")].some(element => element.textContent === text && visible(element))) {
          cleanup();
          resolve();
        } else schedule();
      } catch (error) {
        cleanup();
        reject(error);
      }
    };
    const observer = new MutationObserver(check);
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error(`Initial history readiness exceeded 5000ms: ${id}`));
    }, 5000);
    observer.observe(document.body, { subtree: true, childList: true, attributes: true, characterData: true });
    check();
  });
}

